  main_idea: { statement: "A wealthy girl loses everything and learns to work hard and find hope in a new life.", key_details: ["Esperanza's father dies, and they lose their home.", "They move to a farm camp in California.", "Esperanza works and cares for her sick mother."] },
  text_structure: { type: "Narrative (story structure)", explanation: "The story is told in time order across about one year. Each chapter is named after a fruit or vegetable being harvested, which shows the passing seasons.", signal_words: ["Las Uvas (grapes)", "Las Cebollas (onions)", "Las Almendras (almonds)"], plot: { beginning: "Esperanza lives a rich life in Mexico until her father is killed.", problem: "She must leave everything behind and live as a poor farm worker.", rising_action: "Esperanza struggles to work, Mama gets sick, and workers argue about striking.", climax: "Esperanza discovers her saved money is missing (Miguel used it to bring Abuelita).", resolution: "Abuelita arrives, and Esperanza feels hopeful again." } },
  theme: { statement: "Hope and hard work can help you rise again after losing everything.", topic_word: "resilience", explanation: "Esperanza's name means hope, and she learns to rise up after hard times.", evidence: ["Abuelita teaches her that there is a rhythm to life with ups and downs.", "Esperanza learns to sweep, work, and care for others.", "She gives thanks for what she has at the end."] },
  point_of_view: { type: "Third person limited", explanation: "The narrator uses she and follows Esperanza's thoughts.", evidence: "Readers know how embarrassed Esperanza feels when she doesn't know how to sweep." },
  narrator: { who: "An outside narrator who follows Esperanza", inside_or_outside: "Outside the story", explanation: "Esperanza is not telling the story, but the narrator stays close to her." },
